window.kbPageData["views/entry/k-6f56499ef0661e64"] = {"key":"entry/k-6f56499ef0661e64","state":{"route":"entry/k-6f56499ef0661e64"},"node":{"id":"k-6f56499ef0661e64","mode":"k","title":"着力建设强大国内市场","type":"事实与事件","domain":"经济","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"主类":["事实与事件"],"出处性质":["报告摘登"],"学科":["经济"],"时间索引":["年度事件或数据"],"来源主题":["年度政府工作"],"资料类别":["时政"]},"eventTags":[{"year":2026,"title":"政府工作报告","slug":"94fd2d7ef9a6"}],"directorySummary":"（一）着力建设强大国内市场。坚持内需主导，统筹促消费和扩投资，拓展内需增长\n新空间，更好发挥我国超大规模市场优势。\n深入实施提振消费专项行动。激发居民消费内生动力和促消费政策并举，推动消费持\n续增长。制定实施城乡居民增收计划，在促进低收入群体增收、增加居民财产性收入、完善\n薪酬和社保制度等方面推出一…","sources":[{"id":"e4f3cd1bc70e9deb","label":"着力建设强大国内市场","topic":"年度政府工作","category":"时政","text":"（一）着力建设强大国内市场。坚持内需主导，统筹促消费和扩投资，拓展内需增长\n新空间，更好发挥我国超大规模市场优势。\n深入实施提振消费专项行动。激发居民消费内生动力和促消费政策并举，推动消费持\n续增长。制定实施城乡居民增收计划，在促进低收入群体增收、增加居民财产性收入、完善\n薪酬和社保制度等方面推出一批务实举措。促进商品消费扩容升级，安排超长期特别国债\n2500 亿元支持消费品以旧换新，优化政策实施机制。设立 1000 亿元财政金融协同促内需专\n项资金，组合运用贷款贴息、融资担保、风险补偿等方式，支持扩大内需。扩大个人消费贷\n款和服务业经营主体贷款贴息政策支持领域，提高贴息上限，延长实施期限。实施好一次性\n信用修复政策。实施服务消费提质惠民行动，打造一批带动面广、显示度高的消费新场景，\n加快培育消费新增长点。活跃线下消费，激发下沉市场消费活力。清理消费领域不合理限制\n措施，释放文旅、赛事、康养等领域消费潜力。支持有条件的地方推广中小学春秋假，落实\n职工带薪错峰休假制度。加强消费者权益保护。优化入境消费环境，打造“购在中国”品牌。\n充分挖掘释放有效投资潜力。聚焦新质生产力、新型城镇化、人的全面发展等重点领\n域，增强市场主导的有效投资增长动力，提高民生类政府投资比重。今年拟安排中央预算\n内投资 7550 亿元，安排 8000 亿元超长期特别国债资金用于“两重”建设，分类提高中央投\n资补助标准。单列并提高用于项目建设的地方政府专项债券额度，继续向投资项目准备充分、\n资金用得好的地方倾斜。发行新型政策性金融工具 8000 亿元，带动更多社会资本参与投资。\n统筹用好各类政府投资资金，支持工作基础较好的地方探索编制全口径政府投资计划，加强\n项目资金监管，坚决防止低效无效投资。落实促进民间投资的政策措施，完善民营企业参与\n重大项目建设长效机制，引导民间投资向高技术、现代服务业等新赛道拓展，有效激发民间\n投资活力。","source":{"doc":"6cbfb01fe723bba64b75","first":24,"last":25,"page":24,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"报告摘登"}]},"questions":{},"terms":{},"references":{},"topics":[],"units":{"k-6f56499ef0661e64":[]}};
